import numpy as np
def refract(n1, n2, theta1_deg):
    s = n1 * np.sin(np.deg2rad(theta1_deg)) / n2   # スネルの法則
    if s > 1:
        return None                                # 全反射
    return np.rad2deg(np.arcsin(s))
print("空気→ガラス 30°:", refract(1.0, 1.5, 30))   # 約19.5°
