import numpy as np
def spot(sx, sy, n=15):
    """方向ごとにぼけ幅の違う点像（楕円ガウス）"""
    yy, xx = np.mgrid[0:n, 0:n] - n // 2
    return 255 * np.exp(-(xx**2 / (2 * sx**2) + yy**2 / (2 * sy**2)))
# センサ位置を動かすと横線 -> 円 -> 縦線
for name, sx, sy in [("メリジオナル", 4, 0.6), ("最小錯乱円", 2.2, 2.2), ("サジタル", 0.6, 4)]:
    s = spot(sx, sy)
    w = (s[7] > 64).sum(); h = (s[:, 7] > 64).sum()   # 横幅・縦幅（画素）
    print(f"{name}: 横{w}画素 x 縦{h}画素")
